export type SteeringCompletionStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed"
  | "cancelled";

export type SteeringCompletionResult = unknown;

export interface SteeringCompletion {
  id: string;
  requesterSessionKey: string;
  status: SteeringCompletionStatus;
  result?: SteeringCompletionResult;
  prompt?: string;
  steeringLeaseId?: string;
  steeringLeaseExpiresAt?: number;
  createdAt?: number;
  updatedAt?: number;
}

export interface SteeringLease {
  id: string;
  steeringLeaseId: string;
  completionId: string;
  requesterSessionKey: string;
  result?: SteeringCompletionResult;
  prompt: string;
  leasedAt: number;
  expiresAt: number;
}

export interface SteeringCompletionInput {
  id?: string;
  requesterSessionKey: string;
  result?: SteeringCompletionResult;
  prompt?: string;
  status?: SteeringCompletionStatus;
  createdAt?: number;
  updatedAt?: number;
}

export interface SteeringLeaseOptions {
  requesterSessionKey: string;
  now?: number;
  limit?: number;
  leaseTtlMs?: number;
}

export interface SteeringLeaseEntry {
  completion: SteeringCompletion;
  lease: SteeringLease;
}

const DEFAULT_LEASE_TTL_MS = 5 * 60 * 1000;
const TERMINAL_STATUSES = new Set<SteeringCompletionStatus>([
  "delivered",
  "discarded",
  "failed",
  "cancelled",
]);

let leaseSequence = 0;

function createLeaseId(): string {
  leaseSequence = (leaseSequence + 1) % Number.MAX_SAFE_INTEGER;
  return `steering-lease-${Date.now().toString(36)}-${leaseSequence.toString(36)}`;
}

function completionText(input: SteeringCompletionInput): string {
  if (typeof input.prompt === "string" && input.prompt.length > 0) {
    return input.prompt;
  }
  if (typeof input.result === "string") {
    return input.result;
  }
  if (input.result !== undefined) {
    try {
      return JSON.stringify(input.result);
    } catch {
      return String(input.result);
    }
  }
  return "";
}

function mergePrompt(text: string, result: SteeringCompletionResult): string {
  if (result === undefined) {
    return text;
  }
  if (typeof result === "string") {
    return text.length > 0 ? `${text}\n${result}` : result;
  }
  try {
    const encoded = JSON.stringify(result);
    return text.length > 0 ? `${text}\n${encoded}` : encoded;
  } catch {
    return text.length > 0 ? `${text}\n${String(result)}` : String(result);
  }
}

/**
 * Owns completed steering work between the producing agent and the next turn.
 *
 * A lease is deliberately not an acknowledgement: an acknowledged item is
 * terminal, while a released item returns to pending and can be leased again.
 */
export class AgentSteeringQueue {
  private readonly completions = new Map<string, SteeringCompletion>();
  private readonly acknowledgedLeases = new Set<string>();
  private readonly releasedLeases = new Set<string>();
  private sequence = 0;

  enqueue(input: SteeringCompletionInput): SteeringCompletion {
    const now = Date.now();
    const id = input.id ?? `steering-completion-${now.toString(36)}-${(this.sequence += 1).toString(36)}`;
    const existing = this.completions.get(id);
    const completion: SteeringCompletion = {
      ...(existing ?? {}),
      ...input,
      id,
      requesterSessionKey: input.requesterSessionKey,
      status: input.status ?? existing?.status ?? "pending",
      createdAt: existing?.createdAt ?? input.createdAt ?? now,
      updatedAt: input.updatedAt ?? now,
    };
    if (completion.status !== "in_progress") {
      delete completion.steeringLeaseId;
      delete completion.steeringLeaseExpiresAt;
    }
    this.completions.set(id, completion);
    return { ...completion };
  }

  add(input: SteeringCompletionInput): SteeringCompletion {
    return this.enqueue(input);
  }

  enqueueCompletion(input: SteeringCompletionInput): SteeringCompletion {
    return this.enqueue(input);
  }

  listPending(requesterSessionKey: string): SteeringCompletion[] {
    const now = Date.now();
    return [...this.completions.values()]
      .filter((item) => item.requesterSessionKey === requesterSessionKey)
      .filter((item) => item.status === "pending" || item.status === "suspended")
      .filter((item) => !this.releasedLeases.has(item.steeringLeaseId ?? ""))
      .filter((item) => item.status !== "in_progress" || this.isLeaseStale(item, now))
      .map((item) => ({ ...item }));
  }

  listPendingCompletions(requesterSessionKey: string): SteeringCompletion[] {
    return this.listPending(requesterSessionKey);
  }

  get(id: string): SteeringCompletion | undefined {
    const item = this.completions.get(id);
    return item ? { ...item } : undefined;
  }

  private isLeaseStale(item: SteeringCompletion, now: number): boolean {
    return (
      item.status === "in_progress" &&
      item.steeringLeaseExpiresAt !== undefined &&
      item.steeringLeaseExpiresAt <= now
    );
  }

  leaseCompletions(options: SteeringLeaseOptions): SteeringLease[] {
    const now = options.now ?? Date.now();
    const ttl = options.leaseTtlMs ?? DEFAULT_LEASE_TTL_MS;
    const candidates = [...this.completions.values()]
      .filter((item) => item.requesterSessionKey === options.requesterSessionKey)
      .filter((item) => item.status === "pending" || item.status === "suspended")
      .filter((item) => !this.releasedLeases.has(item.steeringLeaseId ?? ""))
      .filter((item) => item.status !== "in_progress" || this.isLeaseStale(item, now))
      .slice(0, Math.max(0, options.limit ?? Number.POSITIVE_INFINITY));

    return candidates.map((item) => {
      const leaseId = createLeaseId();
      item.status = "in_progress";
      item.steeringLeaseId = leaseId;
      item.steeringLeaseExpiresAt = now + ttl;
      item.updatedAt = now;
      const text = mergePrompt(completionText(item), item.result);
      return {
        id: leaseId,
        steeringLeaseId: leaseId,
        completionId: item.id,
        requesterSessionKey: item.requesterSessionKey,
        result: item.result,
        prompt: text,
        leasedAt: now,
        expiresAt: now + ttl,
      };
    });
  }

  lease(options: SteeringLeaseOptions): SteeringLease[] {
    return this.leaseCompletions(options);
  }

  leasePending(options: SteeringLeaseOptions): SteeringLease[] {
    return this.leaseCompletions(options);
  }

  leasePendingCompletions(options: SteeringLeaseOptions): SteeringLease[] {
    return this.leaseCompletions(options);
  }

  /**
   * Acknowledge a leased completion. The completion id and lease id must both
   * match, otherwise the acknowledgement is ignored.
   */
  ack(steeringLeaseId: string, completionId?: string): boolean {
    const item = completionId
      ? this.completions.get(completionId)
      : this.findByLease(steeringLeaseId);
    if (!item || item.steeringLeaseId !== steeringLeaseId) {
      return false;
    }
    if (this.acknowledgedLeases.has(steeringLeaseId) || this.releasedLeases.has(steeringLeaseId)) {
      return false;
    }
    item.status = "delivered";
    item.updatedAt = Date.now();
    delete item.steeringLeaseId;
    delete item.steeringLeaseExpiresAt;
    this.acknowledgedLeases.add(steeringLeaseId);
    return true;
  }

  ackCompletion(steeringLeaseId: string, completionId?: string): boolean {
    return this.ack(steeringLeaseId, completionId);
  }

  acknowledge(steeringLeaseId: string, completionId?: string): boolean {
    return this.ack(steeringLeaseId, completionId);
  }

  private findByLease(leaseId: string): SteeringCompletion | undefined {
    for (const item of this.completions.values()) {
      if (item.steeringLeaseId === leaseId) {
        return item;
      }
    }
    return undefined;
  }

  release(steeringLeaseId: string, completionId?: string): boolean {
    const item = completionId
      ? this.completions.get(completionId)
      : this.findByLease(steeringLeaseId);
    if (!item || item.steeringLeaseId !== steeringLeaseId) {
      return false;
    }
    if (this.acknowledgedLeases.has(steeringLeaseId) || this.releasedLeases.has(steeringLeaseId)) {
      return false;
    }
    item.status = "pending";
    item.updatedAt = Date.now();
    delete item.steeringLeaseId;
    delete item.steeringLeaseExpiresAt;
    this.releasedLeases.add(steeringLeaseId);
    return true;
  }

  releaseCompletion(steeringLeaseId: string, completionId?: string): boolean {
    return this.release(steeringLeaseId, completionId);
  }

  cancel(completionId: string): boolean {
    const item = this.completions.get(completionId);
    if (!item || TERMINAL_STATUSES.has(item.status)) {
      return false;
    }
    item.status = "cancelled";
    item.updatedAt = Date.now();
    delete item.steeringLeaseId;
    delete item.steeringLeaseExpiresAt;
    return true;
  }

  terminate(completionId: string): boolean {
    return this.cancel(completionId);
  }
}

export const agentSteeringQueue = new AgentSteeringQueue();

export default AgentSteeringQueue;

